window.docContents[126].resolve({"/IntroL/#Sem___ntica-computacional-com-Lean--Programa______o-Funcional-no-Lean--As-duas-leituras-de-uma-fun______o--Composi______o":{"contents":"Componhamos duas conversões: de Kelvin para Celsius, depois de Celsius\npara Fahrenheit. ∘ é Function.comp, e (f ∘ g) x = f (g x) —\nprimeiro g, depois f, na ordem em que a leitura da notação sugere o\ncontrário.\n\ndef kelvinToCelsius (k : Int) : Int := k - 273\n\ndef kelvinToFahrenheit : Int → Int :=\n  celsiusToFahrenheit ∘ kelvinToCelsius\n\n\n#eval kelvinToFahrenheit 373\n\n\n212\n\n\n","context":"Semântica computacional com Lean\u0009Programação Funcional no Lean\u0009As duas leituras de uma função","header":"2.12.1. Composição","id":"/IntroL/#Sem___ntica-computacional-com-Lean--Programa______o-Funcional-no-Lean--As-duas-leituras-de-uma-fun______o--Composi______o"}});